   "s": "令 $f(x)=\\sqrt{1+x}$，$f(0)=1$，$f^{\\prime}(0)=\\frac{1}{2}$，$\\Delta x=0.01$，则 $\\sqrt{1.01}\\approx 1+\\frac{0.01}{2}=1.005$。",
   "c": 2
