   "t": "验证 $f(x)=x^2-2x$ 在 [02] 上满足罗尔定理，并求 ξ。",
   "a": "ξ$=1\\in (0,2)$",
   "s": "f 为多项式，连续可导，$f(0)=0=f(2)$。$f^{\\prime}(x)=2x-2$，令 $f^{\\prime}($ξ$)=0$ 得 ξ$=1\\in (0,2)$。",
   "c": 2
