   "t": "设 $f(x)$ 在 $[0,1]$ 上连续，且 $f(1)=1$。证明：对任意 $\\lambda\\in(0,1)$，存在 $\\xi\\in(0,1)$，使 $f(\\xi)=\\dfrac{\\lambda}{\\xi^{2}}$。",
   "a": "证明见解析。",
