   "s": "逐次求导，每次降一次幂：\n\n$y^{\\prime}=3x^{2}$，$y^{\\prime\\prime}=3\\cdot2x^{1}$……\n\n一般式 $y^{(n)}=\\dfrac{3!}{(3-n)!}x^{3-n}$（$n\\le 3$）；$n>3$ 时为 $0$。",
   "src": "skill",
