   "s": "逐次求导，每次降一次幂：\n\n$y^{\\prime}=4x^{3}$，$y^{\\prime\\prime}=4\\cdot3x^{2}$……\n\n一般式 $y^{(n)}=\\dfrac{4!}{(4-n)!}x^{4-n}$（$n\\le 4$）；$n>4$ 时为 $0$。",
