   "s": "$f^{\\prime}(x)=1-\\dfrac{4}{x^{2}}=\\dfrac{x^{2}-4}{x^{2}}$，驻点 $x=2$（$-2$ 不在区间内）。\n\n算值：$f(1)=5$，$f(2)=4$，$f(4)=5$。\n\n最大 $5$，最小 $4$。",
