   "t": "已知 $F(x)$ 是 $f(x)=3x^{2}$ 的一个原函数，且 $F(1)=4$，求 $F(x)$。",
   "a": "$F(x)=x^{3}+3$",
   "s": "$F(x)=x^{3}+C$，$F(1)=1+C=4\\Rightarrow C=3$。\n\n故 $F(x)=x^{3}+3$。",
   "src": "skill",
