   "t": "已知 $F(x)$ 是 $f(x)=\\dfrac{1}{x}$ 的一个原函数（$x>0$），且 $F(1)=2$，求 $F(x)$。",
   "a": "$F(x)=\\ln x+2$",
   "s": "$F(x)=\\ln x+C$，$F(1)=0+C=2\\Rightarrow C=2$。\n\n故 $F(x)=\\ln x+2$。",
