   "s": "在 $\\dfrac{1}{1-u}=\\displaystyle\\sum u^{n}$ 中令 $u=-2x$：\n\n$\\dfrac{1}{1+2x}=\\displaystyle\\sum_{n=0}^{\\infty}(-2x)^{n}=\\sum_{n=0}^{\\infty}(-1)^{n}2^{n}x^{n}$。\n\n收敛条件 $|-2x|<1$，即 $|x|<\\dfrac{1}{2}$。"
